tailwind:
/* Arbitrary value: exactly the CSS gradient, any Tailwind v4 project. */
bg-[linear-gradient(0deg,#000000,#ff00ff,#00ffff,#ffffff)]

/* Theme variable: use as class "bg-gradient". */
@theme {
  --background-image-gradient: linear-gradient(0deg, #000000, #ff00ff, #00ffff, #ffffff);
}

/* Custom utility: use as class "bg-gradient". */
@utility bg-gradient {
  background-image: linear-gradient(0deg, #000000, #ff00ff, #00ffff, #ffffff);
}

css-variables:
:root {
  --gradient-angle: 0deg;
  --gradient-color-1: #000000;
  --gradient-color-2: #ff00ff;
  --gradient-color-3: #00ffff;
  --gradient-color-4: #ffffff;
  --gradient: linear-gradient(var(--gradient-angle), var(--gradient-color-1), var(--gradient-color-2), var(--gradient-color-3), var(--gradient-color-4));
}

/* Usage: background: var(--gradient); */

